import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"预约 Farrugia 医生","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/dialogues/06-jodie-doctor-appointment.md","filePath":"zh/more/maltese/practice/dialogues/06-jodie-doctor-appointment.md"}'),e={name:"zh/more/maltese/practice/dialogues/06-jodie-doctor-appointment.md"},o=r('<h1 id="预约-farrugia-医生" tabindex="-1">预约 Farrugia 医生 <a class="header-anchor" href="#预约-farrugia-医生" aria-label="Permalink to &quot;预约 Farrugia 医生&quot;">​</a></h1><p><strong>场景：</strong> Jodie 打电话到诊所，预约 Farrugia 医生下周就诊，双方商定周四晚上七点。（说话人标签根据对话语境推断，原文为听力练习。）</p><h2 id="完整对话" tabindex="-1">完整对话 <a class="header-anchor" href="#完整对话" aria-label="Permalink to &quot;完整对话&quot;">​</a></h2><p><strong>Jodie（患者）：</strong> Nista&#39; nagħmel appuntament għall-ġimgħa d-dieħla mat-tabib Farrugia?</p><p><strong>接待员：</strong> Il-ġimgħa d-dieħla għandi vojt l-Erbgħa u l-Ħamis.</p><p><strong>Jodie（患者）：</strong> L-Erbgħa ma nistax, imma l-Ħamis iva. Fi x&#39;hin?</p><p><strong>接待员：</strong> Filgħodu?</p><p><strong>接待员：</strong> Jew filgħaxija?</p><p><strong>Jodie（患者）：</strong> Filgħaxija aħjar, wara x-xogħol.</p><p><strong>接待员：</strong> Fis-6, fis-6:30, jew fis-7pm?</p><p><strong>Jodie（患者）：</strong> Fis-sebgħa tajjeb, grazzi!</p><p><strong>接待员：</strong> Ibbukkajt il-Ħamis fis-sebgħa ta&#39; filgħaxija.</p><p><strong>接待员：</strong> Nikkonferma, saħħa.</p><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><h3 id="_1-jodie-患者" tabindex="-1">1. Jodie（患者） <a class="header-anchor" href="#_1-jodie-患者" aria-label="Permalink to &quot;1. Jodie（患者）&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; nagħmel appuntament għall-ġimgħa d-dieħla mat-tabib Farrugia?</p><p><strong>整句：</strong> 我能不能约下周和 Farrugia 医生见面？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>我能</td><td>第一人称单数</td></tr><tr><td>nagħmel</td><td>我做；我约</td><td>第一人称单数现在时</td></tr><tr><td>appuntament</td><td>预约；约见</td><td>阳性名词，借词 appointment</td></tr><tr><td>għall-ġimgħa</td><td>为下周</td><td><code>għal</code>+<code>il-ġimgħa</code> 缩合</td></tr><tr><td>d-dieħla</td><td>即将到来的</td><td><code>id-dieħla</code>，dieħel 阴性单数带定冠词</td></tr><tr><td>mat-tabib</td><td>和医生</td><td><code>ma&#39;</code>+<code>it-tabib</code> 缩合</td></tr><tr><td>Farrugia</td><td>Farrugia</td><td>医生姓氏</td></tr></tbody></table><h3 id="_2-接待员" tabindex="-1">2. 接待员 <a class="header-anchor" href="#_2-接待员" aria-label="Permalink to &quot;2. 接待员&quot;">​</a></h3><p><strong>Malti:</strong> Il-ġimgħa d-dieħla għandi vojt l-Erbgħa u l-Ħamis.</p><p><strong>整句：</strong> 下周我周三和周四有空。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Il-ġimgħa</td><td>星期</td><td>阴性名词，带定冠词</td></tr><tr><td>d-dieħla</td><td>即将到来的</td><td>修饰 il-ġimgħa</td></tr><tr><td>għandi</td><td>我有</td><td><code>għand</code> 第一人称单数</td></tr><tr><td>vojt</td><td>空；空闲</td><td>名词</td></tr><tr><td>l-Erbgħa</td><td>周三</td><td>带定冠词的星期名</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>l-Ħamis</td><td>周四</td><td>带定冠词的星期名</td></tr></tbody></table><h3 id="_3-jodie-患者" tabindex="-1">3. Jodie（患者） <a class="header-anchor" href="#_3-jodie-患者" aria-label="Permalink to &quot;3. Jodie（患者）&quot;">​</a></h3><p><strong>Malti:</strong> L-Erbgħa ma nistax, imma l-Ħamis iva. Fi x&#39;hin?</p><p><strong>整句：</strong> 周三不行，但周四可以。几点？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>L-Erbgħa</td><td>周三</td><td>带定冠词</td></tr><tr><td>ma nistax</td><td>我不能</td><td><code>ma</code>+<code>nista&#39;</code>+<code>x</code> 构成否定</td></tr><tr><td>imma</td><td>但是</td><td>转折连词</td></tr><tr><td>l-Ħamis</td><td>周四</td><td>带定冠词</td></tr><tr><td>iva</td><td>是的；可以</td><td>肯定应答</td></tr><tr><td>Fi</td><td>在……</td><td>介词 <code>f&#39;</code> 的变体</td></tr><tr><td>x&#39;hin</td><td>什么时间</td><td><code>x&#39;</code>（什么）+ hin（时间）</td></tr></tbody></table><h3 id="_4-接待员" tabindex="-1">4. 接待员 <a class="header-anchor" href="#_4-接待员" aria-label="Permalink to &quot;4. 接待员&quot;">​</a></h3><p><strong>Malti:</strong> Filgħodu?</p><p><strong>整句：</strong> 上午？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Filgħodu</td><td>在上午</td><td><code>f&#39;</code>+<code>il-għodu</code> 缩合；原文拼写 <code>flgħodu</code> 应为 <code>filgħodu</code></td></tr></tbody></table><h3 id="_5-接待员" tabindex="-1">5. 接待员 <a class="header-anchor" href="#_5-接待员" aria-label="Permalink to &quot;5. 接待员&quot;">​</a></h3><p><strong>Malti:</strong> Jew filgħaxija?</p><p><strong>整句：</strong> 还是晚上？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jew</td><td>或者</td><td>连词</td></tr><tr><td>filgħaxija</td><td>在晚上</td><td><code>f&#39;</code>+<code>il-għaxija</code> 缩合</td></tr></tbody></table><h3 id="_6-jodie-患者" tabindex="-1">6. Jodie（患者） <a class="header-anchor" href="#_6-jodie-患者" aria-label="Permalink to &quot;6. Jodie（患者）&quot;">​</a></h3><p><strong>Malti:</strong> Filgħaxija aħjar, wara x-xogħol.</p><p><strong>整句：</strong> 晚上更好，下班后。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Filgħaxija</td><td>在晚上</td><td>时间表达</td></tr><tr><td>aħjar</td><td>更好</td><td><code>tajjeb</code> 的比较级</td></tr><tr><td>wara</td><td>之后</td><td>介词</td></tr><tr><td>x-xogħol</td><td>工作</td><td>阳性名词，带定冠词</td></tr></tbody></table><h3 id="_7-接待员" tabindex="-1">7. 接待员 <a class="header-anchor" href="#_7-接待员" aria-label="Permalink to &quot;7. 接待员&quot;">​</a></h3><p><strong>Malti:</strong> Fis-6, fis-6:30, jew fis-7pm?</p><p><strong>整句：</strong> 6 点、6:30 还是晚上 7 点？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Fis-6</td><td>在 6 点</td><td><code>f&#39;</code>+<code>is-</code>（数字定冠词形式）</td></tr><tr><td>jew</td><td>还是</td><td>选择连词</td></tr><tr><td>fis-7pm</td><td>在晚上 7 点</td><td>pm 表示晚间</td></tr></tbody></table><h3 id="_8-jodie-患者" tabindex="-1">8. Jodie（患者） <a class="header-anchor" href="#_8-jodie-患者" aria-label="Permalink to &quot;8. Jodie（患者）&quot;">​</a></h3><p><strong>Malti:</strong> Fis-sebgħa tajjeb, grazzi!</p><p><strong>整句：</strong> 7 点可以，谢谢！</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Fis-sebgħa</td><td>在 7 点</td><td><code>f&#39;</code>+<code>is-sebgħa</code></td></tr><tr><td>tajjeb</td><td>好的；可以</td><td>形容词</td></tr><tr><td>grazzi</td><td>谢谢</td><td>礼貌用语</td></tr></tbody></table><h3 id="_9-接待员" tabindex="-1">9. 接待员 <a class="header-anchor" href="#_9-接待员" aria-label="Permalink to &quot;9. 接待员&quot;">​</a></h3><p><strong>Malti:</strong> Ibbukkajt il-Ħamis fis-sebgħa ta&#39; filgħaxija.</p><p><strong>整句：</strong> 我订了周四晚上 7 点。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ibbukkajt</td><td>我预订了</td><td>借词 book，第一人称单数过去时</td></tr><tr><td>il-Ħamis</td><td>周四</td><td>带定冠词</td></tr><tr><td>fis-sebgħa</td><td>在 7 点</td><td>时间表达</td></tr><tr><td>ta&#39; filgħaxija</td><td>晚上的</td><td><code>ta&#39;</code>+<code>filgħaxija</code></td></tr></tbody></table><h3 id="_10-接待员" tabindex="-1">10. 接待员 <a class="header-anchor" href="#_10-接待员" aria-label="Permalink to &quot;10. 接待员&quot;">​</a></h3><p><strong>Malti:</strong> Nikkonferma, saħħa.</p><p><strong>整句：</strong> 确认，再见。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nikkonferma</td><td>我确认</td><td>借词 confirm</td></tr><tr><td>saħħa</td><td>保重；再见</td><td>字面&quot;健康&quot;，常用告别语</td></tr></tbody></table>',54),i=[o];function h(s,n,l,g,c,b){return d(),a("div",null,i)}const u=t(e,[["render",h]]);export{m as __pageData,u as default};
